head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.nColCnt = 0;
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.vSecugrpID = $c.lc.fn_getSecuGrpId($c.cm.InfoMenuID()); // (주권)메뉴단에서 파라미터로 받자..
scwin.getPar, scwin.setPar;
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.cm.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        /*  Init  */
        $c.cm.PanelToGroupBox(panel_Top);

        // var vCurDate = cGetToday("yyyymmdd");
        // var vCurMonth = cGetMinusYear(vCurDate, 3);

        // edt_BzSDate.text = vCurMonth;
        // edt_BzEDate.text = vCurDate;

        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp_3);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05626.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05626.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05626.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        /*  Keyboard Event  */
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05626.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        /*  Button Event */
        $c.lc.fn_PopFindCorpChrgSW(scwin.vSecugrpID, "1"); // ST/ "1" : SPAC
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05626.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05626.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        /* New */
        scwin.getPar = scwin.getParNew;
        await scwin.openPopUp();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05626.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        /* Close */
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05626.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        /* Save-Excel */
        if (dts_List.getRowCount() > 0) {
            $c.stf.doLogSave("ULDSTF05626.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewExcel(grd_List, {fileName: $c.lc.fn_getSecuGrpNm(scwin.vSecugrpID) + "존립기간관리목록", type: "8"});
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05626.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        /* Grid Event - DoubleClick */
        scwin.getPar = scwin.getParModify;
        scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
        await scwin.openPopUp();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05626.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name img_BzSDate_onclick
 * @description img_BzSDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_BzSDate_onclick = function() {
    try {
        popUpCalendar2(edt_BzSDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05626.img_BzSDate_onclick" });
    }
};

/**
 * @method
 * @name img_BzEDate_onclick
 * @description img_BzEDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_BzEDate_onclick = function() {
    try {
        popUpCalendar2(edt_BzEDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05626.img_BzEDate_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_3_onselchange
 * @description cmb_PeriodTp_3 onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_3_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp_3, "VALUE", cmb_PeriodTp_3.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_BzSDate, edt_BzEDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05626.cmb_PeriodTp_3_onselchange" });
    }
};

/**
 * @method
 * @name grd_List_OnUserColor
 * @description grd List On User Color 처리
 * @param {Number} row 행 인덱스
 * @param {String} eventId eventId
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnUserColor = function(row, eventId) {
    try {
        const colorName = "#77FF88"; // 11FF00";

        // 변경전 존립기간과 변경후 존립기간 변경  다른 경우 색 표시
        if (scwin.nColCnt > 0) {
            if (eventId === "acolor7") {
                // var bfSD = dts_List.NameValue(row,"BFCHG_EXST_STRT_DD");
                const bfED = dts_List.getCellData(row, "BFCHG_EXST_END_DD");

                // var afSD = dts_List.NameValue(row,"AFCHG_EXST_STRT_DD");
                const afED = dts_List.getCellData(row, "AFCHG_EXST_END_DD");
                if (bfED !== afED) {
                    return colorName; // 연두색
                } else {
                    if (row % 2 === 0) return "#f2f5f9";

                    else return "#ffffff";
                }
            } else if (eventId === "acolor6") {
                const bfSD = dts_List.getCellData(row, "BFCHG_EXST_STRT_DD");
                const afSD = dts_List.getCellData(row, "AFCHG_EXST_STRT_DD");
                if (bfSD !== afSD) {
                    return colorName; // 연두색
                } else {
                    if (row % 2 === 0) return "#f2f5f9";

                    else return "#ffffff";
                }
            }
        }
        if (row % 2 === 0) return "#f2f5f9";

        else return "#ffffff";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05626.grd_List_OnUserColor" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05626.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01; //  01 List
    url += "&method=exstlistMarket&inputMessageId=FISCYY_CHG_INOUT&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&STYPE=1";
    url += "&BZ_SDATE=" + edt_BzSDate.getValue();
    url += "&BZ_EDATE=" + edt_BzEDate.getValue();
    url += "&BF_EXST_MODIFY_YN=" + cmb_ExstModifyYN.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/fiscalYearChange.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.nColCnt = 1;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getPar
 * @description Default Get
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // Default Get

    arrPar[0] = "";
    arrPar[1] = "";
    arrPar[2] = scwin.vSecugrpID;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setPar
 * @description Default Get
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    // Default Get

    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
};

/**
 * @method
 * @name getParModify
 * @description Modify Get
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParModify = function(arrPar) {
    // Modify Get

    arrPar[0] = dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD");
    arrPar[1] = dts_List.getCellData(dts_List.getRowPosition(), "COM_NM");
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO");
    return arrPar.length;
};

//

/**
 * @method
 * @name getParNew
 * @description New Get
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParNew = function(arrPar) {
    // New Get
    arrPar[0] = "";
    arrPar[1] = "";
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = "";
};

/**
 * @method
 * @name openPopUp
 * @description Popup
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openPopUp = async function() {
    const options = {
        id: "ULDSTF05629",
        title: "기업인수목적회사 존립기간 변경관리",
        type: "pageFramePopup",
        width: 665 + 2,
        height: "350px"
    };

    const data = {
        // TO-DO : 팝업으로 전달할 파라미터 설정
    };

    const result = await $c.win.openPopup("/lstproc/ULDSTF05629.gfm", options, data);
    // TO-DO : result 값 확인 후 업무 로직 추가
};
